const key='riyousuode-v1'; const app=document.querySelector('#app'); let db; try{db=JSON.parse(localStorage.getItem(key))||{entries:[],draft:null}}catch{db={entries:[],draft:null}}; let recognition=null; let voiceActive=false; let voiceRestart=null; let recording=null; let pendingAudio=null; let transcribing=false;
function save(){try{localStorage.setItem(key,JSON.stringify(db));scheduleSync();return true}catch(e){alert('本地保存失败，请检查浏览器存储空间或权限。');return false}}
const revisionKey='riyousuode-db-revision';let dbRevision=null,syncEnabled=false,syncTimer=null,syncing=false,syncPending=false;let syncMessage='正在检查本机数据库…';
function setSyncMessage(message){syncMessage=message;const el=document.querySelector('#sync-status');if(el)el.textContent=message}
async function storageApi(payload){const response=await fetch('/api/storage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});let data=await response.json();if(!data.ok)throw new Error(data.error||'数据库不可用');return data.data}
function scheduleSync(){if(!syncEnabled)return;syncPending=true;clearTimeout(syncTimer);syncTimer=setTimeout(flushSync,500)}
async function flushSync(){if(!syncEnabled||syncing||!syncPending)return;syncing=true;syncPending=false;let snapshot=JSON.parse(JSON.stringify(db));setSyncMessage('正在同步到本机数据库…');try{const result=await storageApi({action:'write',snapshot,revision:dbRevision});if(result.conflict){syncEnabled=false;setSyncMessage('数据库有其他版本，自动同步已暂停。请到隐私页面查看和恢复。');return}dbRevision=result.revision;localStorage.setItem(revisionKey,String(dbRevision));setSyncMessage('已同步到本机数据库。')}catch(e){syncPending=true;setSyncMessage('本机数据库同步失败；浏览器草稿仍保留。请到隐私页面重试。')}finally{syncing=false;if(syncEnabled&&syncPending)syncTimer=setTimeout(flushSync,5000)}}
async function initStorage(){if(window.DIARY_API_BASE){setSyncMessage('日记保存在当前浏览器；清除浏览器数据或更换设备可能丢失。');return}try{let remote=await storageApi({action:'read'});let saved=localStorage.getItem(revisionKey);let localHasData=db.entries.length>0||!!db.draft;if(remote.revision===0){dbRevision=0;syncEnabled=true;if(localHasData)scheduleSync();else setSyncMessage('本机数据库已就绪。')}else if(saved!==null&&Number(saved)===remote.revision){dbRevision=remote.revision;syncEnabled=true;if(JSON.stringify(db)!==JSON.stringify(remote.snapshot))scheduleSync();else setSyncMessage('本机数据库已连接。')}else{syncEnabled=false;setSyncMessage('检测到已有数据库记录，自动同步已暂停；请在隐私页面选择恢复。')}}catch(e){setSyncMessage('本机数据库暂不可用，记录仍保存在浏览器。请重启服务后重试。')}}
async function restoreStorage(){try{let remote=await storageApi({action:'read'});if(!remote.snapshot){alert('数据库中暂无记录。');return}if(!confirm('恢复会替换当前浏览器中的日记和草稿。建议先导出当前记录。确定继续？'))return;let previous=db;db=remote.snapshot;try{localStorage.setItem(key,JSON.stringify(db));localStorage.setItem(revisionKey,String(remote.revision))}catch(e){db=previous;throw e}dbRevision=remote.revision;syncEnabled=true;syncPending=false;setSyncMessage('已从本机数据库恢复。');alert('恢复成功。');render()}catch(e){alert('恢复失败，当前浏览器记录未更改。')}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function now(){return new Date().toISOString()}function day(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}function start(){if(db.draft&&!confirm('已有未完成的草稿，开始新记录会替换它。继续吗？'))return;db.draft={id:crypto.randomUUID(),created:now(),date:day(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,step:'write',original:'',text:'',answer:'',question:'',summary:'',happy:'',hard:'',one:'',candidates:[],moods:'',rating:'',version:1};save();location.hash='write';render()}function update(field,value){if(!db.draft)return;db.draft[field]=value;db.draft.updated=now();save()}
let calendarCursor=new Date();calendarCursor.setDate(1);calendarCursor.setHours(12,0,0,0);let selectedDay=day();
function localDate(dateString){if(!/^\d{4}-\d{2}-\d{2}$/.test(dateString))return null;const [year,month,date]=dateString.split('-').map(Number),d=new Date(year,month-1,date,12);return d.getFullYear()===year&&d.getMonth()===month-1&&d.getDate()===date?d:null}
function dateHeading(dateString){const d=localDate(dateString)||new Date();return `<div class="date-heading"><span class="date-number">${d.getDate()}</span><span class="date-meta"><strong>${d.getFullYear()} 年 ${d.getMonth()+1} 月</strong><span>${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][d.getDay()]}</span></span>${dateString===day()?'<span class="date-today">今天</span>':''}</div>`}
function calendarMarkup(){const year=calendarCursor.getFullYear(),month=calendarCursor.getMonth(),first=new Date(year,month,1,12),count=new Date(year,month+1,0,12).getDate(),dates=new Set(db.entries.map(e=>e.date)),empty=Array.from({length:first.getDay()},()=>'<span aria-hidden="true"></span>').join('');let cells='';for(let i=1;i<=count;i++){const date=day(new Date(year,month,i,12)),has=dates.has(date),selected=date===selectedDay;cells+=`<button type="button" class="calendar-day ${selected?'selected':''} ${has?'has-entry':''}" data-calendar-day="${date}" aria-label="${year}年${month+1}月${i}日${has?'，有日记':''}" aria-pressed="${selected}">${i}${has?'<span class="calendar-dot" aria-hidden="true"></span>':''}</button>`}return `<div class="calendar-heading"><button type="button" id="calendar-prev" class="calendar-arrow" aria-label="上个月">‹</button><strong>${year} 年 ${month+1} 月</strong><button type="button" id="calendar-next" class="calendar-arrow" aria-label="下个月">›</button></div><div class="calendar-grid calendar-week" aria-hidden="true">${['日','一','二','三','四','五','六'].map(v=>`<span>${v}</span>`).join('')}</div><div class="calendar-grid">${empty}${cells}</div>`}
function home(){let entries=db.entries.filter(e=>e.date===selectedDay).slice().sort((a,b)=>String(b.created||'').localeCompare(String(a.created||'')));const date=localDate(selectedDay);app.innerHTML=`<section class="hero diary-home"><div class="eyebrow">你的日记</div><h1>今天，<br>想从哪里说起？</h1><p class="lead">不用组织好语言，也不必急着得出答案。说说发生了什么，留一点时间给自己。</p><div class="actions"><button id="start">◉ &nbsp;说说今天</button>${db.draft?'<button class="secondary" id="resume">继续未完成的记录</button>':''}</div></section><section class="card calendar-card" aria-label="日历">${calendarMarkup()}</section><section class="card selected-records"><div class="selected-heading"><div><span class="eyebrow">所选日期</span><h2>${date?`${date.getMonth()+1} 月 ${date.getDate()} 日`:'当天的日记'}</h2></div><button id="calendar-today" class="secondary">回到今天</button></div>${entries.length?entries.map(e=>`<a class="entry" href="#entry/${esc(e.id)}"><span class="muted">${esc(new Date(e.created).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}))} · ${esc(e.moods||'未填写情绪')}</span><strong>${esc(e.one||e.summary||(e.text||'').slice(0,60))}</strong></a>`).join(''):'<p class="muted">这一天还没有日记。</p>'}</section><div class="quick-links" aria-label="日记功能"><a class="quick-link" href="#history"><span class="quick-icon" aria-hidden="true">▤</span><span><strong>日记本</strong><small>查看所有记录</small></span><span aria-hidden="true">›</span></a></div>`;document.querySelector('#start').onclick=start;if(db.draft)document.querySelector('#resume').onclick=()=>{location.hash=db.draft.step};document.querySelector('#calendar-prev').onclick=()=>{calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()-1,1,12);home()};document.querySelector('#calendar-next').onclick=()=>{calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,1,12);home()};document.querySelector('#calendar-today').onclick=()=>{selectedDay=day();calendarCursor=new Date();calendarCursor.setDate(1);calendarCursor.setHours(12,0,0,0);home()};document.querySelectorAll('[data-calendar-day]').forEach(button=>button.onclick=()=>{selectedDay=button.dataset.calendarDay;home()})}
async function ai(kind,d){const response=await window.diaryFetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,text:d.text,question:d.question,answer:d.answer,...(kind==='listen'&&db.memoryEnabled?{memories:(db.memories||[]).filter(m=>m.active!==false&&db.entries.some(e=>e.id===m.sourceId)).slice(0,10).map(m=>m.text)}:{})})});let body;try{body=await response.json()}catch{throw new Error('无法连接日记 AI 服务，请确认已启动 python server.py 并刷新页面。')}if(!body.ok)throw new Error(body.error);return body.data}
function write(){let d=db.draft;if(!d){location.hash='home';return}app.innerHTML=`<section class="page record-page">${dateHeading(d.date)}<div class="record-top"><div class="record-progress" aria-label="记录第一步"><span></span><span></span><span></span></div><a class="record-close" href="./?app=1" aria-label="关闭记录，稍后继续">×</a></div><h2>从最想说的<br>那件事开始。</h2><div class="card record-card"><div class="record-wave" aria-hidden="true">${Array.from({length:27},(_,i)=>`<span style="--wave-delay:${(i%9)*0.11}s;--wave-height:${30+(i%6)*12}%"></span>`).join('')}</div><div class="actions"><button id="voice" class="secondary">◉ 开始语音输入</button><button id="stop" class="secondary">结束并转写</button><button id="retry-voice" class="secondary" hidden>重试转写</button><button id="cancel-voice" class="secondary" hidden>取消录音</button></div><p id="status" class="muted" aria-live="polite"></p><div id="live-preview" class="notice" hidden aria-live="polite"></div><label for="text">今天的讲述</label><textarea id="text" placeholder="今天发生了什么？">${esc(d.text)}</textarea><div class="actions"><button id="next">听我说完了</button><button id="manual" class="secondary">手动整理</button><a class="button" href="#home">稍后继续</a></div></div></section>`;document.querySelector('#text').oninput=e=>update('text',e.target.value);document.querySelector('#manual').onclick=()=>{if(!d.text.trim()){alert('先写下一点内容吧。');return}if(/自杀|杀死自己|自残|杀人|伤害他人|不想活了|结束生命/.test(d.text)){d.step='safety';save();location.hash='safety';return}if(voiceActive||transcribing||pendingAudio){alert('请先结束录音并完成转写，或放弃本段录音。');return}d.step='review';d.manual=true;save();location.hash='review'};document.querySelector('#voice').onclick=()=>voice('text');document.querySelector('#stop').onclick=stopVoice;document.querySelector('#retry-voice').onclick=()=>sendAudio();document.querySelector('#cancel-voice').onclick=cancelVoice;document.querySelector('#next').onclick=async e=>{if(!d.text.trim()){alert('先写下一点内容吧。');return}if(/自杀|杀死自己|自残|杀人|伤害他人|不想活了|结束生命/.test(d.text)){d.step='safety';save();location.hash='safety';return}if(voiceActive||transcribing||pendingAudio){alert('请先结束录音并完成转写，或放弃本段录音。');return}const button=e.currentTarget;button.disabled=true;button.textContent='正在倾听…';try{const result=await ai('listen',d);d.recap=result.recap;d.question=/不想展开|直接总结|别问/.test(d.text)?'':result.question;d.step=d.question?'follow':'review';if(!d.question){const result=await ai('summary',d);applyDraft(d,result)}save();location.hash=d.step}catch(err){alert(err.message+' 文字已保留，可以重试。')}finally{button.disabled=false;button.textContent='听我说完了'}}}

function joinSpeech(existing,part){if(!existing)return part;const space=/[A-Za-z0-9]$/.test(existing)&&/^[A-Za-z0-9]/.test(part)?' ':'';return existing+space+part}
function voiceControls(){return `<div class="actions"><button type="button" id="voice" class="secondary">◉ 语音输入</button><button type="button" id="stop" class="secondary">结束并转写</button><button type="button" id="retry-voice" class="secondary" hidden>重试转写</button><button type="button" id="cancel-voice" class="secondary" hidden>取消录音</button></div><p id="status" class="muted">语音实时发送给阿里云百炼转写，可能产生费用；每段最多 120 秒。</p><div id="live-preview" class="notice" hidden aria-live="polite"></div>`}
function bindVoiceControls(target){document.querySelector('#voice').onclick=()=>voice(target);document.querySelector('#stop').onclick=stopVoice;document.querySelector('#retry-voice').onclick=()=>sendAudio();document.querySelector('#cancel-voice').onclick=cancelVoice}
function saveVoiceText(target,value){if(target==='text'||target==='answer'){update(target,value);return}const route=location.hash.slice(1).split('/'),id=route[1];if(target==='theme-note'&&route[0]==='theme'){const t=(db.themes||[]).find(x=>x.id===id);if(t){t.note=value;t.updated=now();save()}}else if(target==='work-intro'&&route[0]==='work'){const w=(db.works||[]).find(x=>x.id===id);if(w){w.intro=value;save()}}}
function voiceStatus(message){const el=document.querySelector('#status');if(el)el.textContent=message;document.body?.classList?.toggle('recording-active',voiceActive)}
function toggleRetry(show){for(const id of ['retry-voice','cancel-voice']){const el=document.getElementById(id);if(el)el.hidden=!show||(id==='retry-voice'&&!!window.DIARY_API_BASE)}}
function releaseRecording(){if(!recording)return null;let r=recording;recording=null;clearInterval(r.timer);r.processor.disconnect();r.source.disconnect();r.stream.getTracks().forEach(t=>t.stop());r.context.close().catch(()=>{});return r}
function cancelVoice(){voiceActive=false;if(recording?.ws)recording.ws.close();releaseRecording();pendingAudio=null;toggleRetry(false);voiceStatus('已放弃本段录音。已转写的文字仍保留。')}
function wavBlob(chunks,rate){let length=chunks.reduce((n,c)=>n+c.length,0);let merged=new Float32Array(length),offset=0;for(const chunk of chunks){merged.set(chunk,offset);offset+=chunk.length}const outRate=rate>16000?16000:rate;const outputLength=Math.floor(length*outRate/rate);let buffer=new ArrayBuffer(44+outputLength*2),view=new DataView(buffer);function str(pos,value){for(let i=0;i<value.length;i++)view.setUint8(pos+i,value.charCodeAt(i))}str(0,'RIFF');view.setUint32(4,36+outputLength*2,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,outRate,true);view.setUint32(28,outRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,outputLength*2,true);for(let i=0;i<outputLength;i++){let from=Math.floor(i*rate/outRate),to=Math.min(length,Math.floor((i+1)*rate/outRate)),sum=0;for(let j=from;j<to;j++)sum+=merged[j];let v=Math.max(-1,Math.min(1,sum/Math.max(1,to-from)));view.setInt16(44+i*2,v<0?v*32768:v*32767,true)}return new Blob([buffer],{type:'audio/wav'})}
function pcm16(input,rate){const count=Math.floor(input.length*16000/rate),out=new Int16Array(count);for(let i=0;i<count;i++){let from=Math.floor(i*rate/16000),to=Math.max(from+1,Math.floor((i+1)*rate/16000)),sum=0;for(let j=from;j<Math.min(to,input.length);j++)sum+=input[j];let v=Math.max(-1,Math.min(1,sum/(to-from)));out[i]=v<0?v*32768:v*32767}return out.buffer}
function showLive(r){const el=document.querySelector('#live-preview');if(!el)return;let preview=[...r.segments.values()].join('');el.hidden=!preview;el.textContent='实时识别：'+preview}
async function startRealtime(r){return new Promise((resolve)=>{let code=window.diaryCode();let ws=new WebSocket(window.DIARY_API_BASE?window.DIARY_API_BASE.replace(/^http/,'ws')+'/realtime':'ws://127.0.0.1:8766/realtime');if(window.DIARY_API_BASE)ws.onopen=()=>ws.send(code);r.ws=ws;r.segments=new Map();r.realtimeOK=false;r.realtimeDone=new Promise(done=>r.finishRealtime=done);let settled=false;let timer=setTimeout(()=>{if(!settled){settled=true;ws.close();resolve(false)}},12000);ws.binaryType='arraybuffer';ws.onmessage=e=>{let data;try{data=JSON.parse(e.data)}catch{return}if(data.type==='ready'){if(!settled){settled=true;clearTimeout(timer);r.realtimeOK=true;resolve(true)}return}if(data.type==='conversation.item.input_audio_transcription.text'){r.segments.set(data.item_id,(data.text||'')+(data.stash||''));showLive(r)}else if(data.type==='conversation.item.input_audio_transcription.completed'){r.segments.set(data.item_id,data.transcript||'');showLive(r)}else if(data.type==='session.finished'){r.finished=true;r.finishRealtime(true);ws.close()}else if(data.type==='error'){r.realtimeOK=false;r.finishRealtime(false);ws.close()}};ws.onerror=()=>{r.realtimeOK=false;r.finishRealtime(false);if(!settled){settled=true;clearTimeout(timer);resolve(false)}};ws.onclose=()=>{if(!r.finished){r.realtimeOK=false;r.finishRealtime(false)}if(!settled){settled=true;clearTimeout(timer);resolve(false)}}})}
async function voice(target){if(voiceActive||transcribing){voiceStatus('语音正在处理，请稍等。');return}if(pendingAudio){voiceStatus('请先重试或放弃上一段录音。');return}if(!navigator.mediaDevices?.getUserMedia||!window.AudioContext&&!window.webkitAudioContext){voiceStatus('此浏览器不支持录音，请使用新版 Chrome、Edge 或 Safari，或直接输入文字。');return}try{voiceStatus('正在请求麦克风权限…');const stream=await navigator.mediaDevices.getUserMedia({audio:true});const Context=window.AudioContext||window.webkitAudioContext;let context;try{context=new Context({sampleRate:16000});await context.resume()}catch(e){stream.getTracks().forEach(t=>t.stop());throw e}const source=context.createMediaStreamSource(stream),processor=context.createScriptProcessor(4096,1,1);let chunks=[];let capturedSamples=0;let started=Date.now();recording={stream,context,source,processor,chunks,target,started,timer:null};voiceActive=true;const r=recording;voiceStatus('正在连接阿里云实时识别，首次连接可能需要等待…');if(window.DIARY_API_BASE){try{await fetch(window.DIARY_API_BASE+'/health',{signal:AbortSignal.timeout(90000)})}catch{}}let live=await startRealtime(r);if(recording!==r){r.ws?.close();return}started=Date.now();r.started=started;processor.onaudioprocess=e=>{if(recording){let input=e.inputBuffer.getChannelData(0),remaining=context.sampleRate*120-capturedSamples;if(remaining>0){let part=new Float32Array(input.subarray(0,remaining));chunks.push(part);capturedSamples+=part.length;if(r.realtimeOK&&r.ws?.readyState===WebSocket.OPEN){if(r.ws.bufferedAmount>1000000){r.realtimeOK=false;r.ws.close()}else r.ws.send(pcm16(part,context.sampleRate))}}if(capturedSamples>=context.sampleRate*120)stopVoice()}};source.connect(processor);processor.connect(context.destination);stream.getAudioTracks()[0].onended=()=>{if(voiceActive){voiceStatus('麦克风连接中断，正在保留已有录音。');stopVoice()}};recording.timer=setInterval(()=>{if(!recording)return;let seconds=Math.floor((Date.now()-started)/1000);voiceStatus('录音中 '+seconds+' / 120 秒；停顿不会结束，完成后点击“结束并转写”。');if(seconds>=120)stopVoice()},1000);voiceStatus(live?'录音中，文字会实时显示；停顿不会结束。':(window.DIARY_API_BASE?'实时识别未连接，请取消录音后手动输入。':'实时识别未连接，结束后可使用 DeepSeek 转写。'))}catch(e){voiceActive=false;const interrupted=releaseRecording();interrupted?.ws?.close();voiceStatus(e.name==='NotAllowedError'?'麦克风权限被拒绝，请在浏览器地址栏允许麦克风后重试，或输入文字。':'无法启动录音，请检查麦克风、浏览器权限，或直接输入文字。')}}
async function stopVoice(){if(!voiceActive)return;voiceActive=false;const r=releaseRecording();if(!r)return;const samples=r.chunks.reduce((n,c)=>n+c.length,0);if(samples<r.context.sampleRate/2){r.ws?.close();voiceStatus('录音太短或没有采集到声音，请重新录制。');return}let peak=0;for(const chunk of r.chunks)for(const sample of chunk)peak=Math.max(peak,Math.abs(sample));if(peak<0.001){r.ws?.close();voiceStatus('没有检测到声音，请检查麦克风后重新录制。');return}pendingAudio={blob:wavBlob(r.chunks,r.context.sampleRate),target:r.target};transcribing=true;voiceStatus('正在完成实时识别，请稍候…');let success=false;if(r.realtimeOK&&r.ws?.readyState===WebSocket.OPEN){r.ws.send('finish');success=await Promise.race([r.realtimeDone,new Promise(resolve=>setTimeout(()=>resolve(false),22000))])}r.ws?.close();transcribing=false;if(success&&pendingAudio){const text=[...r.segments.values()].join('');const el=document.querySelector('#'+r.target);if(text&&el){el.value=joinSpeech(el.value,text);saveVoiceText(r.target,el.value);if(r.target==='text'){db.draft.original=joinSpeech(db.draft.original,text);save()}pendingAudio=null;const preview=document.querySelector('#live-preview');if(preview)preview.hidden=true;voiceStatus('转写完成，你可以检查和修改文字。');return}}voiceStatus(window.DIARY_API_BASE?'实时识别未完成，可取消录音后手动输入文字。':'实时识别未完成，录音暂存在当前页面。可重试使用 DeepSeek 转写，或放弃录音后手动输入。');toggleRetry(true)}
async function sendAudio(){if(!pendingAudio||transcribing)return;transcribing=true;toggleRetry(false);const audio=pendingAudio;voiceStatus('正在转写，请稍候…');try{const response=await window.diaryFetch('/api/transcribe',{method:'POST',headers:{'Content-Type':'audio/wav'},body:audio.blob});const body=await response.json();if(!body.ok)throw new Error(body.error);const el=document.querySelector('#'+audio.target);if(!el||pendingAudio!==audio)return;el.value=joinSpeech(el.value,body.data.text);saveVoiceText(audio.target,el.value);if(audio.target==='text'){db.draft.original=joinSpeech(db.draft.original,body.data.text);save()}pendingAudio=null;voiceStatus('转写完成，你可以检查和修改文字。')}catch(e){voiceStatus('转写失败，录音暂存在当前页面。请点击重试，或放弃录音后输入文字。');toggleRetry(true)}finally{transcribing=false}}
function follow(){let d=db.draft;if(!d)return home();app.innerHTML=`<section class="page"><a class="record-close record-close-inline" href="./?app=1" aria-label="关闭记录，稍后继续">×</a><div class="eyebrow">倾听 · 一次追问</div><h2>再多说一点，也可以</h2><div class="card"><p class="muted">${esc(d.recap||'')}</p><h3>${esc(d.question)}</h3><div id="live-preview" class="notice" hidden aria-live="polite"></div><label for="answer">你的补充</label><textarea id="answer" placeholder="写下你愿意分享的部分">${esc(d.answer)}</textarea><div class="actions"><button id="voice" class="secondary">◉ 语音回答</button><button id="stop" class="secondary">结束并转写</button><button id="retry-voice" class="secondary" hidden>重试转写</button><button id="cancel-voice" class="secondary" hidden>取消录音</button></div><p id="status" class="muted">语音将实时发送给阿里云百炼转写，可能产生费用；每段最多 120 秒。</p><div class="actions"><button id="continue">继续整理</button><button id="skip" class="secondary">跳过，直接整理</button></div></div></section>`;document.querySelector('#answer').oninput=e=>update('answer',e.target.value);document.querySelector('#voice').onclick=()=>voice('answer');document.querySelector('#stop').onclick=stopVoice;document.querySelector('#retry-voice').onclick=()=>sendAudio();document.querySelector('#cancel-voice').onclick=cancelVoice;async function go(skip){if(/自杀|杀死自己|自残|杀人|伤害他人|不想活了|结束生命/.test(d.answer)){d.step='safety';save();location.hash='safety';return}if(voiceActive||transcribing||pendingAudio){voiceStatus('请先结束录音并完成转写，或放弃本段录音。');return}d.skipped=skip;if(skip)d.answer='';save();const buttons=[document.querySelector('#continue'),document.querySelector('#skip')];buttons.forEach(b=>b.disabled=true);document.querySelector('#status').textContent='正在整理…';try{const result=await ai('summary',d);applyDraft(d,result);d.step='review';save();location.hash='review'}catch(err){document.querySelector('#status').textContent=err.message+'，内容已保留，请重试。'}finally{buttons.forEach(b=>b.disabled=false)}}document.querySelector('#continue').onclick=()=>go(false);document.querySelector('#skip').onclick=()=>go(true)}
function applyDraft(d,result){d.aiDraft=result;d.summary=result.summary;d.happy=result.happy;d.hard=result.hard;d.one=result.one;d.candidates=result.moods}

function review(){let d=db.draft;if(!d)return home();app.innerHTML=`<section class="page"><a class="record-close record-close-inline" href="./?app=1" aria-label="关闭记录，稍后继续">×</a><div class="eyebrow">整理 · 由你确认</div><h2>留下属于你的版本</h2><p class="notice">${d.manual?'手动填写你想留下的内容。':'以下为 DeepSeek 的整理建议，请检查并修改；最终内容由你确认。'}</p><div class="card">${[['summary','发生了什么'],['happy','开心的时刻'],['hard','难受或消耗'],['one','想留下的一句话']].map(([id,label])=>`<label for="${id}">${label}</label><textarea id="${id}">${esc(d[id])}</textarea>`).join('')}<p class="muted">AI 情绪候选：${(d.candidates||[]).map(m=>esc(m.label)+'（依据：'+esc(m.evidence)+'）').join('；')||'暂无'}。请自行填写或选择是否采纳。</p><label for="moods">确认情绪（可自填，最多三个，用逗号分隔）</label><input id="moods" value="${esc(d.moods)}" placeholder="例如：平静、疲惫"><label for="rating">整体感受（可选，1–5）</label><select id="rating"><option value="">暂不填写</option>${[1,2,3,4,5].map(n=>`<option ${String(d.rating)===String(n)?'selected':''}>${n}</option>`).join('')}</select><div class="actions"><button id="finish">保存日记</button><a class="button" href="#home">稍后继续</a></div></div></section>`;['summary','happy','hard','one','moods','rating'].forEach(id=>document.querySelector('#'+id).oninput=e=>update(id,e.target.value));document.querySelector('#finish').onclick=()=>{if(d.moods.split(/[,，]/).filter(x=>x.trim()).length>3){alert('最多填写三个情绪。');return}d.status='complete';d.updated=now();const oldEntries=db.entries;db.entries=[...db.entries.filter(e=>e.id!==d.id),d];db.draft=null;if(save())location.hash='history';else{db.entries=oldEntries;db.draft=d}}}
function history(){app.innerHTML=`<section class="page"><div class="eyebrow">YOUR JOURNAL</div><h2>日记</h2><p class="muted">那些被记下的日子，都在这里。</p><div class="card">${db.entries.length?[...db.entries].reverse().map(e=>`<a class="entry" href="#entry/${e.id}"><span class="muted">${esc(e.date)} · ${new Date(e.created).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</span><strong>${esc(e.one||e.summary.slice(0,60))}</strong><span class="muted">${esc(e.moods||'未填写情绪')}</span></a>`).join(''):'<p class="muted">这里还没有日记。等你想记录时再来就好。</p>'}</div></section>`}
function entry(id){let e=db.entries.find(x=>x.id===id);if(!e){location.hash='history';return}app.innerHTML=`<section class="page"><a href="#history" class="muted">‹ 返回日记</a><h2>${esc(e.date)}</h2><div class="card">${[['发生了什么',e.summary],['开心的时刻',e.happy],['难受或消耗',e.hard],['一句话',e.one],['确认的情绪',e.moods],['整体感受',e.rating],...((e.original&&e.original.trim()!==e.text.trim())?[['确认的讲述',e.text],['最初转写',e.original]]:[['讲述',e.text]]),['追问',e.question],['补充',e.skipped?'已跳过':e.answer]].map(([k,v])=>`<h3>${k}</h3><p>${esc(v||'—').replace(/\n/g,'<br>')}</p>`).join('')}<p class="muted">创建 ${esc(e.created)} · 时区 ${esc(e.timezone)}</p><div class="actions"><button id="edit">编辑整理</button><button id="save-memory" class="secondary">记住这件事</button><button class="danger" id="delete">删除这篇日记</button></div></div></section>`;document.querySelector('#edit').onclick=()=>{location.hash='edit/'+e.id};document.querySelector('#save-memory').onclick=()=>{location.hash='memory-add/'+e.id};document.querySelector('#delete').onclick=()=>{if(confirm('确定删除这篇日记？此操作无法撤销。')){db.entries=db.entries.filter(x=>x.id!==id);db.memories=(db.memories||[]).filter(m=>m.sourceId!==id);save();location.hash='history'}}}
function editEntry(id){let e=db.entries.find(x=>x.id===id);if(!e){location.hash='history';return}app.innerHTML=`<section class="page"><a class="muted" href="#entry/${esc(id)}">‹ 返回日记</a><h2>编辑整理</h2><div class="card">${[['summary','发生了什么'],['happy','开心的时刻'],['hard','难受或消耗'],['one','一句话'],['moods','确认情绪，最多三个，逗号分隔']].map(([k,label])=>`<label for="edit-${k}">${label}</label><textarea id="edit-${k}">${esc(e[k]||'')}</textarea>`).join('')}<label for="edit-rating">整体感受（可选）</label><select id="edit-rating"><option value="">暂不填写</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${String(e.rating)===String(n)?'selected':''}>${n}</option>`).join('')}</select><div class="actions"><button id="save-edit">保存修改</button></div></div></section>`;document.querySelector('#save-edit').onclick=()=>{let changes={};['summary','happy','hard','one','moods','rating'].forEach(k=>changes[k]=document.querySelector('#edit-'+k).value);if(changes.moods.split(/[,，]/).filter(x=>x.trim()).length>3){alert('最多填写三个情绪。');return}let previous=db.entries;db.entries=db.entries.map(x=>x.id===id?{...x,...changes,updated:now()}:x);if(save())location.hash='entry/'+id;else db.entries=previous}}
function recentDays(count=7){let dates=[];for(let i=count-1;i>=0;i--){let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-i);dates.push(day(d))}return dates}
let insightRange=7;
function moodChart(dates,entries){const width=700,height=220,left=36,right=20,top=20,bottom=34,step=(width-left-right)/Math.max(1,dates.length-1);const groups=dates.map(date=>entries.filter(e=>e.date===date&&['1','2','3','4','5'].includes(String(e.rating))));const xy=(i,value)=>[left+i*step,top+(5-Number(value))*(height-top-bottom)/4];let grid=[1,2,3,4,5].map(n=>{let y=xy(0,n)[1];return `<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" stroke="#e9e0e9"/><text x="10" y="${y+5}" font-size="14" fill="#74667a">${n}</text>`}).join('');let lines='';for(let i=1;i<groups.length;i++){if(groups[i-1].length===1&&groups[i].length===1){let a=xy(i-1,groups[i-1][0].rating),b=xy(i,groups[i][0].rating);lines+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#ae7da7" stroke-width="2"/>`}}let points=groups.map((items,i)=>items.map((e,j)=>{let [x,y]=xy(i,e.rating);x+=(j-(items.length-1)/2)*5;return `<circle cx="${x}" cy="${y}" r="5" fill="#775a80"><title>${esc(e.date)} 感受 ${esc(e.rating)}，详情见下方列表</title></circle>`}).join('')).join('');return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="整体感受趋势图；详细日期和评分见下方列表">${grid}${lines}${points}<text x="${left}" y="${height-5}" font-size="13" fill="#74667a">${esc(dates[0])}</text><text x="${width-right}" y="${height-5}" text-anchor="end" font-size="13" fill="#74667a">${esc(dates.at(-1))}</text></svg>`}
function insights(){const dates=recentDays(insightRange);const entries=db.entries.filter(e=>dates.includes(e.date));const recordedDays=new Set(entries.map(e=>e.date)).size;const rated=entries.filter(e=>['1','2','3','4','5'].includes(String(e.rating)));const moodCounts={};entries.forEach(e=>String(e.moods||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean).forEach(m=>{moodCounts[m]=(moodCounts[m]||0)+1}));const topMoods=Object.entries(moodCounts).sort((a,b)=>b[1]-a[1]).slice(0,3);app.innerHTML=`<section class="page"><div class="eyebrow">回顾 · 你留下的日子</div><h2>最近的日子</h2><p class="muted">只使用你填写的整体感受。没有评分的日子保持为空，同一天多条记录分别展示。</p><div class="actions"><button id="days7" class="${insightRange===7?'':'secondary'}">近 7 天</button><button id="days30" class="${insightRange===30?'':'secondary'}">近 30 天</button></div><div class="card"><h3>这段时间的记录</h3><p>${entries.length?`你在 ${recordedDays} 天里留下了 ${entries.length} 条记录，其中 ${rated.length} 条填写了整体感受。`:'这段时间还没有记录，等你想记录时再来就好。'}</p><p class="muted">${topMoods.length?'你确认过的情绪：'+topMoods.map(([m,n])=>esc(m)+'（'+n+' 次）').join('、'):'尚无已确认的情绪。'}</p></div><div class="card"><h3>AI 回顾</h3><p class="muted">点击生成时，会将这段时间的日记整理与已确认情绪发送给 DeepSeek，可能产生费用。</p><button id="make-review" ${entries.length?'':'disabled'}>生成这段时间的回顾</button><div id="review-result" aria-live="polite"></div></div><div class="card"><h3>整体感受</h3><p class="muted">1–5 是你的主观感受，并非医学评分。仅在相邻两天各有一条评分时连线。</p><div class="chart">${moodChart(dates,entries)}</div></div><div class="card"><h3>按日期查看</h3>${dates.slice().reverse().map(date=>{let items=entries.filter(e=>e.date===date);return `<div class="day-row"><strong>${esc(date.slice(5))}</strong><div>${items.length?items.map(e=>`<a class="day-entry" href="#entry/${esc(e.id)}">${e.rating?'感受 '+esc(e.rating)+'/5':'未评分'} · ${esc(e.one||e.summary||'查看记录')}</a>`).join(''):'<span class="muted">没有记录</span>'}</div></div>`}).join('')}</div><div class="card"><h3>留下的片段</h3>${entries.length?entries.slice().reverse().map(e=>`<a class="entry" href="#entry/${esc(e.id)}"><span class="muted">${esc(e.date)} · ${esc(e.moods||'未填写情绪')}</span><strong>${esc(e.one||e.summary||e.text)}</strong></a>`).join(''):'<p class="muted">还没有这段时间的记录，等你想记录时再来就好。</p>'}</div></section>`;document.querySelector('#make-review').onclick=async e=>{if(entries.length>50){alert('这段时间记录超过 50 条，请先切换到较短的时间范围。');return}if(!confirm('将这段时间的日记整理和确认情绪发送给 DeepSeek 生成回顾，可能产生费用。继续吗？'))return;const button=e.currentTarget,box=document.querySelector('#review-result');button.disabled=true;box.textContent='正在整理…';try{const selected=entries.map(({id,date,summary,happy,hard,one,moods})=>({id,date,summary,happy,hard,one,moods}));const res=await window.diaryFetch('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entries:selected})});const body=await res.json();if(!body.ok)throw new Error(body.error);box.innerHTML=`<p>${esc(body.data.overview)}</p>${body.data.highlights.map(x=>`<a class="entry" href="#entry/${esc(x.source_id)}">${esc(x.text)}<br><span class="muted">查看对应日记</span></a>`).join('')}<p class="muted">由 AI 生成，请结合原文核对。</p>`}catch(err){box.textContent='回顾暂时无法生成，请稍后重试。'}finally{button.disabled=false}};document.querySelector('#days7').onclick=()=>{insightRange=7;insights()};document.querySelector('#days30').onclick=()=>{insightRange=30;insights()}}

function themeDate(value){if(!value)return '尚未记录编辑时间';const date=new Date(value);return Number.isNaN(date.getTime())?'尚未记录编辑时间':'更新于 '+date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function themeSnippet(t){const passage=(Array.isArray(t.passages)?t.passages:[]).slice().reverse().find(p=>typeof p.text==='string'&&p.text.trim());return String(passage?.text||t.note||'').trim()}
function themes(){const list=Array.isArray(db.themes)?[...db.themes]:[];list.sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||String(b.updated||'').localeCompare(String(a.updated||'')));app.innerHTML=`<section class="page"><a class="muted" href="#insights">‹ 返回回顾</a><h2>生活主题</h2><p class="muted">为想持续关注的人、事或感受留一个空间。主题由你管理，不会自动用于新的 AI 追问。</p><div class="card"><label for="theme-name">新主题</label><input id="theme-name" maxlength="40" placeholder="例如：慢慢学会休息"><div class="actions"><button id="add-theme">创建主题</button></div></div><div class="card">${list.length?list.map(t=>`<a class="entry" href="#theme/${esc(t.id)}"><strong>${t.pinned?'📌 ':''}${esc(t.name)}</strong><span class="muted">${(t.entryIds||[]).filter(id=>db.entries.some(e=>e.id===id)).length} 条日记 · ${esc(themeDate(t.updated))}</span><span class="theme-snippet">${themeSnippet(t)?'最近的想法：'+esc(themeSnippet(t).slice(0,80)):'写下一点关于这个主题的想法'}</span></a>`).join(''):'<p class="muted">还没有主题。你可以为想持续关注的事创建一个。</p>'}</div></section>`;document.querySelector('#add-theme').onclick=()=>{const name=document.querySelector('#theme-name').value.trim();if(!name){alert('先填写主题名称。');return}if(!Array.isArray(db.themes))db.themes=[];const item={id:crypto.randomUUID(),name,entryIds:[],note:'',passages:[],photos:[],columns:2,pinned:false,created:now(),updated:now()};db.themes.push(item);if(save())location.hash='theme/'+item.id;else db.themes.pop()}}
function theme(id){const t=(db.themes||[]).find(x=>x.id===id);if(!t){location.hash='themes';return}const passages=Array.isArray(t.passages)?t.passages:[];const columns=[1,2,3].includes(Number(t.columns))?Number(t.columns):2;app.innerHTML=`<section class="page"><a class="muted" href="#themes">‹ 返回生活主题</a><h2>${esc(t.name)}</h2><p class="muted">${esc(themeDate(t.updated))}</p><div class="card"><label for="theme-title">主题名称</label><input id="theme-title" maxlength="40" value="${esc(t.name)}"><label for="theme-note">这个主题对你的意义</label><textarea id="theme-note" placeholder="你为什么想留下这个主题？">${esc(t.note||'')}</textarea>${voiceControls()}<label class="pick-row"><input id="theme-pin" type="checkbox" ${t.pinned?'checked':''}><span>置顶这个主题</span></label></div><div class="card"><h3>文字与感受</h3><p class="muted">不同时刻的想法可以分开留下。</p><div id="passage-list">${passages.map((v,i)=>`<div class="passage"><label for="passage-${i}">${esc(v.created?themeDate(v.created).replace('更新于','记录于'):'一段想法')}</label><textarea id="passage-${i}" data-passage-index="${i}" placeholder="写下此刻的感受">${esc(v.text||'')}</textarea><button type="button" class="secondary" data-remove-passage="${i}">移除这段文字</button></div>`).join('')}</div><div class="actions"><button id="add-passage" class="secondary">添加一段文字</button></div></div><div class="card"><h3>关联的日记</h3><p class="muted">选择和这个主题有关的日记，之后可以回到原文。</p>${db.entries.length?db.entries.slice().reverse().map(e=>`<label class="pick-row"><input type="checkbox" data-entry="${esc(e.id)}" ${(t.entryIds||[]).includes(e.id)?'checked':''}><span><strong>${esc(e.date)}</strong><br>${esc((e.one||e.summary||e.text||'').slice(0,100))}</span></label>`).join(''):'<p class="muted">保存日记后，可以在这里添加。</p>'}</div><div class="card"><h3>回看这个主题</h3><p class="muted">你可以主动生成回顾，AI 将读取此主题的意义、文字和关联日记；生成前需要确认。</p><button id="theme-review" class="secondary">生成主题回顾</button><div id="theme-review-result" aria-live="polite"></div></div><div class="actions"><button id="save-theme">保存主题</button><button id="preview-theme" class="secondary">预览主题</button><button id="delete-theme" class="danger">删除主题</button></div></section>`;
 bindVoiceControls('theme-note');
 function persist(){if(voiceActive||transcribing||pendingAudio){alert('请先完成或放弃当前录音。');return false}let name=document.querySelector('#theme-title').value.trim();if(!name){alert('主题名称不能为空。');return false}const old={...t};t.name=name;t.note=document.querySelector('#theme-note').value;t.pinned=document.querySelector('#theme-pin').checked;t.entryIds=[...document.querySelectorAll('[data-entry]:checked')].map(x=>x.dataset.entry);t.passages=passages.map((v,i)=>({...v,text:document.querySelector('#passage-'+i).value}));t.updated=now();if(!save()){Object.assign(t,old);return false}return true}
 document.querySelector('#add-passage').onclick=()=>{if(!persist())return;t.passages.push({id:crypto.randomUUID(),created:now(),text:''});if(save())theme(id);else t.passages.pop()};
 document.querySelectorAll('[data-remove-passage]').forEach(btn=>btn.onclick=()=>{if(!persist())return;const prior=t.passages;t.passages=prior.filter((_,i)=>i!==Number(btn.dataset.removePassage));if(save())theme(id);else t.passages=prior});
 document.querySelector('#theme-review').onclick=async e=>{if(!persist())return;const entries=db.entries.filter(item=>(t.entryIds||[]).includes(item.id));if(entries.length>30){alert('关联日记超过 30 条，请先减少关联后重试。');return}if(!confirm('将此主题的名称、意义、文字和已关联日记发送给 DeepSeek 生成回顾，可能产生费用。继续吗？'))return;const button=e.currentTarget,box=document.querySelector('#theme-review-result');button.disabled=true;box.textContent='正在整理主题…';try{const payload={theme:{name:t.name,note:t.note,passages:t.passages},entries:entries.map(({id,date,text,answer,summary,one,moods})=>({id,date,text,answer,summary,one,moods}))};const res=await fetch('/api/theme-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await res.json();if(!result.ok)throw Error(result.error);box.innerHTML=`<p>${esc(result.data.overview)}</p>${result.data.highlights.map(x=>`<a class="entry" href="#entry/${esc(x.source_id)}">${esc(x.text)}<br><span class="muted">查看对应日记</span></a>`).join('')}<p class="muted">由 AI 生成，请对照原文核对。</p>`}catch(err){box.textContent=err.message||'回顾暂时无法生成，请稍后重试。'}finally{button.disabled=false}};
 document.querySelector('#save-theme').onclick=()=>{if(persist())location.hash='themes'};document.querySelector('#preview-theme').onclick=()=>{if(persist())location.hash='theme-preview/'+id};document.querySelector('#delete-theme').onclick=()=>{if(!confirm('删除主题？已关联的日记仍会保留。'))return;const prev=db.themes;db.themes=prev.filter(x=>x.id!==id);if(save())location.hash='themes';else db.themes=prev}}
function themePreview(id){const t=(db.themes||[]).find(x=>x.id===id);if(!t){location.hash='themes';return}const entries=db.entries.filter(e=>(t.entryIds||[]).includes(e.id));app.innerHTML=`<section class="page"><a class="muted" href="#theme/${esc(id)}">‹ 返回编辑</a><h2>${esc(t.name)}</h2><p class="muted">${esc(themeDate(t.updated))}</p><div class="card"><h3>这个主题的意义</h3><p>${esc(t.note||'暂未填写').replace(/\n/g,'<br>')}</p>${(t.passages||[]).filter(v=>v.text?.trim()).map(v=>`<article class="work-entry"><span class="muted">${esc(v.created?themeDate(v.created).replace('更新于','记录于'):'')}</span><p>${esc(v.text).replace(/\n/g,'<br>')}</p></article>`).join('')}<h3>关联日记</h3>${entries.length?entries.map(e=>`<a class="entry" href="#entry/${esc(e.id)}"><span class="muted">${esc(e.date)}</span><strong>${esc(e.one||e.summary||e.text)}</strong></a>`).join(''):'<p class="muted">还没有关联日记。</p>'}</div></section>`}
function works(){const works=Array.isArray(db.works)?db.works:[];app.innerHTML=`<section class="page"><div class="eyebrow">YOUR COLLECTION</div><h2>我的作品</h2><p class="muted">选取自己的日记，加上当下想说的话，留下一份私人作品。</p><div class="card"><label for="work-name">作品名称</label><input id="work-name" maxlength="60" placeholder="例如：慢慢学会休息"><div class="actions"><button id="add-work">创建作品</button></div></div><div class="card">${works.length?works.map(w=>`<a class="entry" href="#work/${esc(w.id)}"><strong>${esc(w.title)}</strong><span class="muted">${(w.entryIds||[]).filter(id=>db.entries.some(e=>e.id===id)).length} 条日记</span></a>`).join(''):'<p class="muted">还没有作品。随时可以从一段想保留的经历开始。</p>'}</div></section>`;document.querySelector('#add-work').onclick=()=>{let title=document.querySelector('#work-name').value.trim();if(!title){alert('先填写作品名称。');return}if(!Array.isArray(db.works))db.works=[];let w={id:crypto.randomUUID(),title,intro:'',entryIds:[]};db.works.push(w);if(save())location.hash='work/'+w.id;else db.works.pop()}}
function safePhotoUrl(value){return typeof value==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value)?value:''}
function photosHtml(w,editable){return (Array.isArray(w.photos)?w.photos:[]).map((photo,i)=>{let src=safePhotoUrl(photo.data);if(!src)return '';return `<figure class="photo-item"><img src="${src}" alt="作品照片 ${i+1}">${editable?`<button type="button" class="secondary" data-remove-photo="${i}">移除照片</button>`:''}</figure>`}).join('')}
function work(id){const w=(db.works||[]).find(x=>x.id===id);if(!w){location.hash='works';return}app.innerHTML=`<section class="page"><a class="muted" href="#works">‹ 返回作品</a><h2>${esc(w.title)}</h2><div class="card"><label for="work-title">作品名称</label><input id="work-title" maxlength="60" value="${esc(w.title)}"><label for="work-intro">写给这段经历的话</label><textarea id="work-intro">${esc(w.intro||'')}</textarea>${voiceControls()}<h3>作品照片</h3><label for="work-photo">选择照片</label><input id="work-photo" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="photo-grid">${photosHtml(w,true)}</div><h3>选择收录的日记</h3>${db.entries.length?db.entries.slice().reverse().map(e=>`<label class="pick-row"><input type="checkbox" data-work-entry="${esc(e.id)}" ${(w.entryIds||[]).includes(e.id)?'checked':''}><span><strong>${esc(e.date)}</strong><br>${esc((e.one||e.summary||e.text||'').slice(0,100))}</span></label>`).join(''):'<p class="muted">保存日记后，可以在这里添加。</p>'}<h3>编排与注释</h3>${(w.entryIds||[]).map((entryId,i)=>{const e=db.entries.find(v=>v.id===entryId);return e?`<div class="work-order-item"><strong>${esc(e.date)} · ${esc((e.one||e.summary||e.text||'').slice(0,60))}</strong><div class="actions"><button type="button" class="secondary" data-work-move="${i}" data-direction="-1" ${i===0?'disabled':''}>上移</button><button type="button" class="secondary" data-work-move="${i}" data-direction="1" ${i===(w.entryIds||[]).length-1?'disabled':''}>下移</button></div></div>`:''}).join('')||'<p class="muted">选中日记并保存后，就可以在这里编排。</p>'}<div class="actions"><button id="save-work">保存作品</button><button id="preview-work" class="secondary">预览作品</button><button id="delete-work" class="danger">删除作品</button></div></div></section>`;bindVoiceControls('work-intro');function persist(){if(voiceActive||transcribing||pendingAudio){alert('请先完成或放弃当前录音。');return false}let title=document.querySelector('#work-title').value.trim();if(!title){alert('作品名称不能为空。');return false}let previous={...w};w.title=title;w.intro=document.querySelector('#work-intro').value;const checked=[...document.querySelectorAll('[data-work-entry]:checked')].map(x=>x.dataset.workEntry);const previousIds=Array.isArray(w.entryIds)?w.entryIds:[];w.entryIds=[...previousIds.filter(entryId=>checked.includes(entryId)),...checked.filter(entryId=>!previousIds.includes(entryId))];if(!save()){Object.assign(w,previous);return false}return true}document.querySelectorAll('[data-work-move]').forEach(button=>button.onclick=()=>{if(!persist())return;const index=Number(button.dataset.workMove),next=index+Number(button.dataset.direction),prior=[...w.entryIds];if(next<0||next>=w.entryIds.length)return;[w.entryIds[index],w.entryIds[next]]=[w.entryIds[next],w.entryIds[index]];if(save())work(id);else w.entryIds=prior});document.querySelector('#work-photo').onchange=async e=>{if(!persist())return;const files=[...e.target.files],prior=Array.isArray(w.photos)?w.photos:[];if(prior.length+files.length>3){alert('每个作品最多添加 3 张照片。');return}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>1024*1024)){alert('请选择不超过 1 MB 的 JPG、PNG 或 WebP 图片。');return}try{const read=f=>new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve({data:reader.result});reader.onerror=reject;reader.readAsDataURL(f)});const photos=await Promise.all(files.map(read));if(!(db.works||[]).includes(w))return;w.photos=[...prior,...photos];if(!save()){w.photos=prior;return}work(id)}catch{alert('照片读取失败，请重试。')}};document.querySelectorAll('[data-remove-photo]').forEach(btn=>btn.onclick=()=>{if(!persist())return;let prior=w.photos;w.photos=prior.filter((_,i)=>i!==Number(btn.dataset.removePhoto));if(save())work(id);else w.photos=prior});document.querySelector('#save-work').onclick=()=>{if(persist())location.hash='works'};document.querySelector('#preview-work').onclick=()=>{if(persist())location.hash='work-preview/'+id};document.querySelector('#delete-work').onclick=()=>{if(!confirm('删除作品？原日记仍会保留。'))return;let prev=db.works;db.works=prev.filter(x=>x.id!==id);if(save())location.hash='works';else db.works=prev}}
function workPreview(id){const w=(db.works||[]).find(x=>x.id===id);if(!w){location.hash='works';return}const entries=(w.entryIds||[]).map(entryId=>db.entries.find(e=>e.id===entryId)).filter(Boolean);app.innerHTML=`<section class="page"><a class="muted" href="#work/${esc(id)}">‹ 返回编辑</a><h2>${esc(w.title)}</h2><div class="card"><p>${esc(w.intro||'').replace(/\n/g,'<br>')}</p><div class="photo-grid">${photosHtml(w,false)}</div>${entries.length?entries.map(e=>`<article class="work-entry"><span class="muted">${esc(e.date)}</span><p>${esc(e.one||e.summary||e.text).replace(/\n/g,'<br>')}</p><a href="#entry/${esc(e.id)}">查看原日记</a></article>`).join(''):'<p class="muted">还没有选入日记。</p>'}<button id="export-work">导出文本</button></div></section>`;document.querySelector('#export-work').onclick=()=>{const content=[w.title,w.intro,...entries.map(e=>e.date+'\n'+(e.one||e.summary||e.text))].join('\n\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));link.download='日有所得-作品.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}}

function memory(){const memories=Array.isArray(db.memories)?db.memories:[];app.innerHTML=`<section class="page"><a class="muted" href="./?app=1&amp;tab=settings">‹ 返回设置</a><h2>长期记忆</h2><div class="card"><p>从日记中选择值得记住的事，由你填写和确认。记忆可随时修改、暂停或删除。</p><label class="pick-row"><input type="checkbox" id="memory-enabled" ${db.memoryEnabled?'checked':''}><span>在生成追问时使用已启用的记忆</span></label><p class="muted">开启后，最多 10 条已启用记忆会与当前讲述一起发送给 DeepSeek；关闭后不会发送。删除原日记会同时删除相关记忆。</p></div><div class="card"><h3>我记住的事</h3>${memories.length?memories.map(m=>`<div class="work-order-item"><label for="memory-${esc(m.id)}">记忆</label><textarea id="memory-${esc(m.id)}" maxlength="300">${esc(m.text)}</textarea><p><a href="#entry/${esc(m.sourceId)}">查看来源日记</a></p><label class="pick-row"><input type="checkbox" data-memory-active="${esc(m.id)}" ${m.active!==false?'checked':''}><span>启用这条记忆</span></label><div class="actions"><button class="secondary" data-memory-save="${esc(m.id)}">保存修改</button><button class="danger" data-memory-delete="${esc(m.id)}">删除</button></div></div>`).join(''):'<p class="muted">还没有记忆。打开一篇日记，点击“记住这件事”即可添加。</p>'}</div></section>`;document.querySelector('#memory-enabled').onchange=e=>{if(e.target.checked&&!confirm('开启后，在生成追问时会将你启用的记忆与当前讲述发送给 DeepSeek，可能产生费用。确定开启吗？')){e.target.checked=false;return}let previous=db.memoryEnabled;db.memoryEnabled=e.target.checked;if(!save()){db.memoryEnabled=previous;e.target.checked=!!previous}};document.querySelectorAll('[data-memory-save]').forEach(b=>b.onclick=()=>{let m=memories.find(x=>x.id===b.dataset.memorySave),value=document.getElementById('memory-'+m.id).value.trim();if(!value){alert('记忆内容不能为空。');return}let old={...m};m.text=value;m.active=document.querySelector('[data-memory-active="'+m.id+'"]')?.checked!==false;m.updated=now();if(!save())Object.assign(m,old);else alert('记忆已保存。')});document.querySelectorAll('[data-memory-delete]').forEach(b=>b.onclick=()=>{if(!confirm('删除这条记忆？原日记不会删除。'))return;const previous=db.memories;db.memories=memories.filter(m=>m.id!==b.dataset.memoryDelete);if(save())memory();else db.memories=previous})}
function memoryAdd(id){const e=db.entries.find(x=>x.id===id);if(!e){location.hash='memory';return}app.innerHTML=`<section class="page"><a class="muted" href="#entry/${esc(id)}">‹ 返回日记</a><h2>记住这件事</h2><div class="card"><p class="muted">写下你希望记住的内容。保存后可以修改、暂停或删除。</p><label for="memory-new">记忆内容</label><textarea id="memory-new" maxlength="300">${esc(e.one||e.summary||'')}</textarea><button id="memory-add">保存记忆</button></div></section>`;document.querySelector('#memory-add').onclick=()=>{const text=document.querySelector('#memory-new').value.trim();if(!text){alert('先写下你想记住的内容。');return}if(!Array.isArray(db.memories))db.memories=[];db.memories.push({id:crypto.randomUUID(),sourceId:id,text,active:true,created:now()});if(save())location.hash='memory';else db.memories.pop()}}
function settings(){if(window.DIARY_API_BASE){app.innerHTML=`<section class="page"><h2>隐私与数据</h2><div class="card"><p>日记只保存在当前浏览器；清除浏览器数据或更换设备可能丢失。语音和 AI 请求会发送给对应服务处理。</p><div class="actions"><button id="export-local">导出 JSON 备份</button></div></div></section>`;document.querySelector('#export-local').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='日有所得.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};return}app.innerHTML=`<section class="page"><div class="eyebrow">YOUR SPACE</div><h2>隐私与数据</h2><div class="card"><h3>你的记录</h3><p id="sync-status">${esc(syncMessage)}</p><p>日记先保存在当前浏览器，并同步到这台电脑的本机数据库；这不是云备份，也不支持跨设备同步。录音时，音频会发送给阿里云百炼实时转写；实时转写失败时，可选择发送给 DeepSeek 重试。两种服务均可能产生费用。音频仅临时保存在当前页面内存中，刷新或离开页面会清除，本应用不保存原始音频。</p><p>请求追问和整理时，本篇讲述及回答会发送给 DeepSeek 处理；不会发送其他日记。请查阅 DeepSeek 隐私政策及数据处理条款。本产品用于个人记录，不提供诊断或治疗。</p><div class="actions"><button id="sync-retry" class="secondary">重试数据库同步</button><button id="restore-db" class="secondary">从本机数据库恢复</button><button id="export">导出 JSON</button><button id="textExport" class="secondary">导出文本</button><button id="clear" class="danger">删除全部数据</button></div></div></section>`;function download(data,name,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}document.querySelector('#sync-retry').onclick=()=>{if(syncEnabled){syncPending=true;flushSync()}else initStorage()};document.querySelector('#restore-db').onclick=restoreStorage;document.querySelector('#export').onclick=()=>download(JSON.stringify(db,null,2),'日有所得.json','application/json');document.querySelector('#textExport').onclick=()=>download(db.entries.map(e=>`${e.date}\n${e.text}\n追问：${e.question}\n回答：${e.answer}\n整理：${e.summary}\n情绪：${e.moods}`).join('\n\n---\n\n'),'日有所得.txt','text/plain');document.querySelector('#clear').onclick=()=>{if(confirm('确定删除所有日记和草稿？此操作无法撤销。')){db={entries:[],draft:null};save();location.hash='home'}}}
function safety(){app.innerHTML=`<section class="page"><div class="warning"><h2>先照顾好眼前的安全</h2><p>听起来你可能正面临很难承受的情况。请尽快联系可信任的人陪伴你。如果你或他人正处于紧急危险中，请立即联系当地急救或警方，或前往最近的急诊。你不必独自面对。</p><p>你的草稿仍保存在本机。</p><a href="#home" class="button">返回首页</a></div></section>`}function render(){if(voiceActive||pendingAudio)cancelVoice();let [route,id]=location.hash.slice(1).split('/');document.body?.classList?.toggle('recording-flow',['write','follow','review'].includes(route));const todayTab=document.querySelector('#tab-today'),diaryTab=document.querySelector('#tab-diary'),insightsTab=document.querySelector('#tab-insights'),worksTab=document.querySelector('#tab-works'),settingsTab=document.querySelector('#tab-settings');const active=['settings','memory','memory-add'].includes(route)?'settings':['works','work','work-preview'].includes(route)?'works':['insights','themes','theme','theme-preview'].includes(route)?'insights':['write','follow','review','safety','home'].includes(route)?'today':'diary';for(const [tab,name] of [[todayTab,'today'],[diaryTab,'diary'],[insightsTab,'insights'],[worksTab,'works'],[settingsTab,'settings']]){tab?.classList?.toggle('active',active===name);tab?.setAttribute?.('aria-current',active===name?'page':'false')}({home,write,follow,review,history,insights,settings,safety,memory,'memory-add':()=>memoryAdd(id),themes,theme:()=>theme(id),'theme-preview':()=>themePreview(id),works,work:()=>work(id),'work-preview':()=>workPreview(id),entry:()=>entry(id),edit:()=>editEntry(id)}[route]||home)()}document.addEventListener?.('click',e=>{const link=e.target.closest?.('a[href^="#"]');if(link&&(voiceActive||pendingAudio||transcribing)&&!confirm('本段录音尚未完成转写，离开后将丢失。确定离开吗？'))e.preventDefault()});window.addEventListener('beforeunload',event=>{if(voiceActive||transcribing||pendingAudio){event.preventDefault();event.returnValue=''}});window.addEventListener('hashchange',render);render();initStorage();
